// ------------------------------------------------------------------ randomness
function rng(seed) {
  let s = seed >>> 0 || 1;
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296);
}
function noise1(r, n, k = 6) {
  const c = Array.from({ length: k + 2 }, () => r() * 2 - 1);
  return Array.from({ length: n }, (_, i) => {
    const t = (i / Math.max(1, n - 1)) * k;
    const a = Math.floor(t);
    const f = t - a;
    const s = f * f * (3 - 2 * f);
    return c[a] * (1 - s) + c[a + 1] * s;
  });
}
const f1 = (n) => (Math.round(n * 10) / 10).toString();

// ------------------------------------------------------------------ marks
/** Tapered ink strand along points: filled polygon, width w, swelling in the middle, slight wobble. */
function strand(pts, { w = 10, seed = 1, wobble = 0.0, taperIn = 0.15, taperOut = 0.35 } = {}) {
  if (pts.length < 3) return '';
  const r = rng(seed);
  const nz = noise1(r, pts.length, 5);
  const L = [];
  const R = [];
  for (let i = 0; i < pts.length; i++) {
    const t = i / (pts.length - 1);
    const [x, y] = pts[i];
    const [ax, ay] = pts[Math.max(0, i - 1)];
    const [bx, by] = pts[Math.min(pts.length - 1, i + 1)];
    const dx = bx - ax;
    const dy = by - ay;
    const l = Math.hypot(dx, dy) || 1;
    const nx = -dy / l;
    const ny = dx / l;
    const taper = Math.min(1, t / taperIn, (1 - t) / taperOut);
    const ww = Math.max(0.6, (w / 2) * Math.max(0.08, taper) * (1 + 0.35 * nz[i]));
    const o = wobble * nz[(i * 3) % pts.length];
    L.push([x + nx * (ww + o), y + ny * (ww + o)]);
    R.push([x - nx * (ww - o), y - ny * (ww - o)]);
  }
  return `M${[...L, ...R.reverse()].map(([x, y]) => `${f1(x)} ${f1(y)}`).join('L')}Z`;
}
const poly = (pts) => `M${pts.map(([x, y]) => `${f1(x)} ${f1(y)}`).join('L')}`;
const circleP = (cx, cy, r) => `M${f1(cx - r)} ${f1(cy)}a${f1(r)} ${f1(r)} 0 1 0 ${f1(2 * r)} 0a${f1(r)} ${f1(r)} 0 1 0 ${f1(-2 * r)} 0Z`;
function splatter(r, cx, cy, spread, n, size) {
  let d = '';
  for (let i = 0; i < n; i++) {
    const a = r() * Math.PI * 2;
    const dist = spread * Math.sqrt(-2 * Math.log(r() + 1e-9)) * 0.5;
    d += circleP(cx + Math.cos(a) * dist, cy + Math.sin(a) * dist, size * (0.15 + r() ** 3 * 1.6));
  }
  return d;
}
/** brushed spray of short flicks, the "graffiti" texture */
function flicks(r, cx, cy, spread, n, len, w) {
  let d = '';
  for (let i = 0; i < n; i++) {
    const a = r() * Math.PI * 2;
    const dist = spread * r();
    const x = cx + Math.cos(a) * dist;
    const y = cy + Math.sin(a) * dist;
    const b = a + (r() - 0.5) * 0.8;
    const l = len * (0.3 + r());
    d += strand([[x, y], [x + Math.cos(b) * l * 0.5, y + Math.sin(b) * l * 0.5], [x + Math.cos(b) * l, y + Math.sin(b) * l]], { w: w * (0.4 + r()), seed: (r() * 1e9) | 0, taperIn: 0.05, taperOut: 0.9 });
  }
  return d;
}
function crosshair(cx, cy, rad) {
  return `${circleP(cx, cy, rad).replace('Z', '')} M${f1(cx - rad * 1.5)} ${f1(cy)}L${f1(cx + rad * 1.5)} ${f1(cy)} M${f1(cx)} ${f1(cy - rad * 1.5)}L${f1(cx)} ${f1(cy + rad * 1.5)}`;
}
function axis(x, y, len, ticks, vertical = false) {
  let d = vertical ? `M${x} ${y}L${x} ${y - len}` : `M${x} ${y}L${x + len} ${y}`;
  for (let i = 0; i <= ticks; i++) {
    const p = (len / ticks) * i;
    d += vertical ? ` M${x - 10} ${f1(y - p)}L${x + 10} ${f1(y - p)}` : ` M${f1(x + p)} ${y - 10}L${f1(x + p)} ${y + 10}`;
  }
  return d;
}

// ------------------------------------------------------------------ text
/** Text with fallback fonts and light markup: _{sub} ^{sup} _x ^x. Returns { d, width }. */
function typeset(str, x, y, size, fonts, { anchor = 'start', jitter = 0, seed = 1 } = {}) {
  const r = rng(seed);
  const runs = [];
  for (let i = 0; i < str.length; i++) {
    let ch = str[i];
    let mode = 0;
    if ((ch === '_' || ch === '^') && i + 1 < str.length) {
      mode = ch === '_' ? 1 : -1;
      if (str[i + 1] === '{') {
        const end = str.indexOf('}', i);
        for (const c of str.slice(i + 2, end)) runs.push({ c, mode });
        i = end;
        continue;
      }
      ch = str[++i];
    }
    runs.push({ c: ch, mode });
  }
  let cx = 0;
  const glyphs = runs.map(({ c, mode }) => {
    const f = fonts.find((ft) => ft.charToGlyph(c).index > 0) || fonts[fonts.length - 1];
    const sz = mode ? size * 0.62 : size;
    const g = f.charToGlyph(c);
    const item = { f, g, x: cx, dy: mode === 1 ? size * 0.22 : mode === -1 ? -size * 0.42 : 0, sz, rot: (r() - 0.5) * jitter, dyj: (r() - 0.5) * jitter * size * 0.02 };
    cx += (g.advanceWidth / f.unitsPerEm) * sz;
    return item;
  });
  const x0 = anchor === 'middle' ? x - cx / 2 : anchor === 'end' ? x - cx : x;
  const d = glyphs.map((it) => it.g.getPath(x0 + it.x, y + it.dy + it.dyj, it.sz).toPathData(1)).join('');
  return { d, width: cx };
}
const hand = (s, x, y, size, o = {}) => typeset(s, x, y, size, [F.hand, F.math], { jitter: 3, ...o }).d;
const note = (s, x, y, size, o = {}) => typeset(s, x, y, size, [F.handLight, F.math], { jitter: 2, ...o }).d;
const math = (s, x, y, size, o = {}) => typeset(s, x, y, size, [F.math, F.mathUp], o).d;
const mono = (s, x, y, size, o = {}) => typeset(s, x, y, size, [F.mono, F.mathUp], o).d;

// ------------------------------------------------------------------ canvas
const W = 3000;
const H = 4000;

function frame(r, d, idx, title, field, size = 300, capsule = 1) {
  // title lettering, number, field, construction marks, signature
  d.main.push(hand(title, 260, 560, size, { seed: idx * 7 }));
  d.main.push(strand([[270, 640], [900, 628], [1600, 650], [2050, 636]], { w: 16, seed: idx * 11, taperOut: 0.6 }));
  d.main.push(mono(String(idx).padStart(2, '0'), 2740, 330, 90, { anchor: 'end' }));
  d.soft.push(mono(field.toUpperCase(), 2740, 440, 54, { anchor: 'end' }));
  d.soft.push(mono(`ALGEBRA · GRAPHIC SERIES · CAPSULE 0${capsule}`, 260, 3830, 46));
  d.mainPaths.push(`<g transform="translate(2590 3660) scale(1.5)"><path d="${brand.symbol}"/></g>`);
  d.wire.push(crosshair(2600, 3180, 60), crosshair(2640, 900, 46), axis(2760, 3420, 300, 6, true), axis(260, 3700, 420, 7));
  d.splat.push(splatter(r, 2400, 760, 260, 40, 14), splatter(r, 2300, 3150, 220, 30, 12));
}

