      for (let g = 0; g < 7; g++) {
        const a = r() * Math.PI * 2;
        const dist = 650 + r() * 520;
        const gx = cx + Math.cos(a) * dist;
        const gy = cy + Math.sin(a) * dist;
        const sz = 50 + r() * 70;
        for (const arm of [0, Math.PI]) {
          const pts = Array.from({ length: 40 }, (_, i) => { const th = arm + i * 0.11; const rr = sz * (0.1 + Math.pow(i / 39, 1.3)); return [gx + Math.cos(th) * rr, gy + Math.sin(th) * rr * 0.6]; });
          (g % 2 ? d.accent : d.main).push(strand(pts, { w: 5, seed: g * 10 + (arm ? 1 : 0), taperIn: 0.05, taperOut: 0.6 }));
        }
      }
      d.splat.push(splatter(r, cx, cy, 1300, 260, 8));
      d.accent.push(flicks(r, cx, cy, 1200, 40, 90, 10));
      d.soft.push(note('t = 0', cx + 60, cy - 60, 90), note('13.8 billion years', cx + 820, cy + 1180, 90));
      d.main.push(math('H^2 = 8πGρ/3 − kc^2/a^2 + Λc^2/3', 300, 3360, 100));
      d.soft.push(note('Friedmann equation · H = (da/dt)/a', 300, 3490, 80), note('everything, from almost nothing', 2700, 3680, 100, { anchor: 'end' }));
