function back(id, tone) {
  const def = designs[id];
  const ink = (def.capsule === 2 ? INKS2 : INKS)[tone];
  const r = rng(def.idx * 1000 + 7);
  const d = { main: [], accent: [], accent2: [], soft: [], wire: [], wA: [], wA2: [], splat: [], mainPaths: [] };
  def.draw(r, d, tone);
  frame(r, d, def.idx, def.title, def.field, def.titleSize, def.capsule || 1);
  const fill = (c, arr, op = 1) => (arr.length ? `<path fill="${c}"${op < 1 ? ` opacity="${op}"` : ''} d="${arr.join(' ')}"/>` : '');
  const stroke = (c, arr, w, op = 1) => (arr.length ? `<path fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" opacity="${op}" d="${arr.join(' ')}"/>` : '');
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="300mm" height="400mm">
<title>Algebra Graphic Series 0${def.idx} ${def.title}, back print (${tone} garments)</title>
${stroke(ink.soft, d.wire, 4, 0.9)}${stroke(ink.accent, d.wA, 5, 0.9)}${stroke(ink.accent2, d.wA2, 6, 0.9)}
${fill(ink.accent, d.accent)}${fill(ink.accent2, d.accent2)}${fill(ink.main, d.main)}${fill(ink.soft, d.soft)}${fill(ink.main, d.splat, 0.9)}
<g fill="${ink.main}">${d.mainPaths.join('')}</g>
</svg>
`;
}

function front(id, tone) {
  const def = designs[id];
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 900 900" width="70mm" height="70mm">
<title>Algebra Graphic Series 0${def.idx} ${def.title}, chest icon (${tone} garments)</title>
${def.icon ? def.icon(INKS[tone].main) : `<g transform="translate(150 150) scale(6)"><path fill="${INKS[tone].main}" d="${brand.symbol}"/></g>`}
</svg>
`;
}

export const physics = Object.fromEntries(Object.entries(designs).map(([k, v]) => [k, { idx: v.idx, title: v.title, field: v.field }]));

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1];
if (isMain) {
  for (const id of Object.keys(designs)) {
    const dir = join(root, 'capsule', id);
    mkdirSync(dir, { recursive: true });
    for (const tone of ['light', 'dark']) {
      writeFileSync(join(dir, `back-${tone}.svg`), back(id, tone));
      writeFileSync(join(dir, `front-${tone}.svg`), front(id, tone));
    }
  }
  const mod = process.env.PLAYWRIGHT_MODULE;
  if (mod) {
    const { chromium } = await import(pathToFileURL(mod).href);
    const browser = await chromium.launch();
    const px = (mm) => Math.round((mm / 25.4) * 300);
    for (const id of Object.keys(designs)) {
      for (const f of ['back-light', 'back-dark', 'front-light', 'front-dark']) {
        const [w, h] = f.startsWith('back') ? [px(300), px(400)] : [px(70), px(70)];
        const page = await browser.newPage({ viewport: { width: w, height: h } });
        const svg = readFileSync(join(root, 'capsule', id, `${f}.svg`), 'utf8').replace(/width="[^"]+" height="[^"]+"/, `width="${w}" height="${h}"`);
        await page.setContent(`<html><body style="margin:0;background:transparent">${svg}</body></html>`);
        await page.screenshot({ path: join(root, 'capsule', id, `${f}.png`), omitBackground: true, clip: { x: 0, y: 0, width: w, height: h } });
        await page.close();
      }
    }
    await browser.close();
  }
  console.log('physics capsule written', mod ? '(svg + png 300 dpi)' : '(svg)');
}
